886: fn classify(
887:     record: &Record,
888:     report: Option<&RunnerReport>,
889:     cleanup_complete: bool,
890: ) -> Option<(Ending, &'static str)> {
891:     if !record
892:         .events
893:         .iter()
894:         .any(|event| matches!(event.fact, NativeFact::Clean))
895:     {
896:         return None;
897:     }
898:     let started = record
899:         .events
900:         .iter()
901:         .position(|event| matches!(event.fact, NativeFact::Start));
902:     let finish = record
903:         .events
904:         .iter()
905:         .enumerate()
906:         .find_map(|(index, event)| match &event.fact {
907:             NativeFact::Finish { status } => Some((index, status)),
908:             _ => None,
909:         });
910:     let cancel = record.events.iter().position(|event| matches!(&event.fact, NativeFact::Exception { exception_type, severity: 0, .. } if exception_type == "cancel"));
911:     let fatal = record.events.iter().position(|event| matches!(&event.fact, NativeFact::Exception { exception_type, severity: 0, .. } if exception_type != "cancel"));
912:     if !cleanup_complete {
913:         return None;
914:     }
915:     if record.container_launches.keys().any(|execution| {
916:         !record
917:             .runtime_ownerships
918:             .iter()
919:             .any(|owned| &owned.execution == execution)
920:     }) && report.is_none_or(|report| report.outcome != ReportOutcome::PostBeginLaunchFailure)
921:     {
922:         return None;
923:     }
924:     if report.is_some_and(|report| report.outcome == ReportOutcome::PostBeginLaunchFailure) {
925:         // collect() reaches classification only after validating the fresh external
926:         // exact-unit absence alongside every local candidate evidence requirement.
927:         return Some((
928:             Ending::InfraLost,
929:             "post-begin launch/setup failure; nonzero launchers, no container observations and fresh external exact-unit absence",
930:         ));
931:     }
