3: pub(super) fn ownership(record: &Record, owned: &RuntimeOwnership) -> Result<()> {
4:     owned.run.validate()?;
5:     if !token(&owned.execution) {
6:         return Err(BackendError::invalid("invalid runtime execution token"));
7:     }
8:     if owned.run.instance != record.intent.instance
9:         || owned.run.uri != record.intent.uri
10:         || record
11:             .binding
12:             .as_ref()
13:             .is_some_and(|binding| binding.id != owned.run)
14:         || owned.owner.owner != record.intent.owner
15:         || owned.owner.correlation != record.intent.correlation
16:         || owned.request_digest != record.intent.request_digest
17:         || !record.dispatched
18:         || owned.host != "dl380g10"
19:         || owned.rank != 0
20:         || owned.launcher.pid <= 1
21:         || owned.launcher.start_ticks == 0
22:         || owned.process_group <= 1
23:     {
24:         return Err(BackendError::invalid(
25:             "runtime ownership differs from retained dispatch",
26:         ));
27:     }
28:     match (&record.request.runtime.runtime, &owned.container) {
29:         (ExecutionRuntime::Native { .. } | ExecutionRuntime::RootlessPodman { .. }, None) => {}
30:         (ExecutionRuntime::RootlessPodman { mode, .. }, Some(container)) => {
31:             let labels = super::lifecycle::labels(owned);
32:             if container.mode != *mode
33:                 || !hex(&container.id, 64)
34:                 || container.labels != labels
35:                 || !token(&container.name)
36:             {
37:                 return Err(BackendError::invalid(
38:                     "container mode/ID/ownership labels mismatch",
39:                 ));
40:             }
41:             match (mode, &container.scope) {
42:                 (ContainerMode::InJob, None) => {}
43:                 (ContainerMode::OwnScope, Some(scope)) => {
44:                     if !scope.unit.ends_with(".scope")
45:                         || !token(&scope.unit)
46:                         || !hex(&scope.invocation_id, 32)
47:                         || !absolute(Path::new(&scope.cgroup))
48:                         || !scope
49:                             .cgroup
50:                             .starts_with("/user.slice/user-1000.slice/user@1000.service/")
51:                         || !scope.cgroup.ends_with(&format!("/{}", scope.unit))
52:                     {
53:                         return Err(BackendError::invalid(
54:                             "owned scope identity is missing or unsafe",
55:                         ));
56:                     }
57:                 }
58:                 _ => {
59:                     return Err(BackendError::invalid(
60:                         "scope does not match selected container mode",
61:                     ));
62:                 }
63:             }
64:         }
65:         _ => {
66:             return Err(BackendError::invalid(
67:                 "runtime/container ownership shape mismatch",
68:             ));
69:         }
70:     }
71:     Ok(())

